"""Build persisted AG-UI messages from a completed pydantic-ai run.

Copilot v2 stores each turn as an ordered list of AG-UI Message rows so a
rehydrated thread reads exactly as it streamed. Rather than re-accumulate the
stream, this module reads pydantic-ai's own record of the run — the ordered
``ModelMessage`` parts on the run result — and maps them into AG-UI rows.
Because the parts already carry the real interleaving (reasoning, text, tool
calls, tool returns, more text, ...), stream order falls out for free.

Row rules (kept identical to what the client saw stream):
- Each ``ThinkingPart`` is its own reasoning row.
- Consecutive ``TextPart``s with no other part between them merge into one
  assistant text row, because the mapper keeps a single text section open
  across them and streams them as one message; anything else in between (a
  tool call, tool return, or reasoning) starts a fresh text row.
- Consecutive tool calls with no other part between them share one assistant
  row; text and tool calls never share a row.
- A tool return (or a tool-scoped retry) is its own ``tool`` row and ends any
  open tool-call grouping.
"""

from __future__ import annotations

import json
import uuid
from collections.abc import Sequence
from typing import Any

try:
    from pydantic_ai.messages import (
        ModelMessage,
        RetryPromptPart,
        TextPart,
        ThinkingPart,
        ToolCallPart,
        ToolReturnPart,
    )
except ImportError as exc:
    raise ImportError(
        "pydantic-ai-slim is required for Copilot v2. "
        "Install with: pip install rasa-pro[copilot-v2]"
    ) from exc


def rows_from_run_messages(
    new_messages: Sequence[ModelMessage],
) -> list[dict[str, Any]]:
    """Map a completed run's new messages to ordered AG-UI message rows.

    Walks every part of every message in order. User/system prompt parts are
    ignored here — the latest user message is persisted separately from the
    request so the stored turn is not polluted with the concatenated prompt.
    """
    rows: list[dict[str, Any]] = []
    for message in new_messages:
        for part in message.parts:
            _append_part(rows, part)
    return rows


def _append_part(rows: list[dict[str, Any]], part: object) -> None:
    """Append the AG-UI row(s) for one pydantic-ai message part, in place."""
    if isinstance(part, TextPart):
        _append_text(rows, part)
    elif isinstance(part, ThinkingPart):
        _append_thinking(rows, part)
    elif isinstance(part, ToolCallPart):
        _append_tool_call(rows, part)
    elif isinstance(part, ToolReturnPart):
        _append_tool_return(rows, part)
    elif isinstance(part, RetryPromptPart):
        _append_retry(rows, part)
    # UserPromptPart, SystemPromptPart, InstructionPart, and any future part
    # kinds carry nothing we persist for the assistant turn and are skipped.


def _append_text(rows: list[dict[str, Any]], part: TextPart) -> None:
    if not part.content:
        return
    open_row = _open_text_row(rows)
    if open_row is not None:
        # The mapper streamed consecutive text parts as one open section (one
        # message), so persist them as one row by concatenating verbatim — no
        # separator, matching how the deltas were streamed.
        open_row["content"] += part.content
        return
    rows.append(
        {
            "id": part.id or f"msg-{uuid.uuid4().hex}",
            "role": "assistant",
            "content": part.content,
        }
    )


def _append_thinking(rows: list[dict[str, Any]], part: ThinkingPart) -> None:
    if not part.content and not part.signature:
        return
    row: dict[str, Any] = {
        "id": part.id or f"think-{uuid.uuid4().hex}",
        "role": "reasoning",
        "content": part.content or "",
    }
    if part.signature:
        row["encryptedValue"] = part.signature
    rows.append(row)


def _append_tool_call(rows: list[dict[str, Any]], part: ToolCallPart) -> None:
    tool_call = {
        "id": part.tool_call_id,
        "type": "function",
        "function": {
            "name": part.tool_name,
            "arguments": part.args_as_json_str(),
        },
    }
    open_row = _open_tool_call_row(rows)
    if open_row is not None:
        open_row["toolCalls"].append(tool_call)
    else:
        rows.append(
            {
                "id": f"msg-{uuid.uuid4().hex}",
                "role": "assistant",
                "content": "",
                "toolCalls": [tool_call],
            }
        )


def _append_tool_return(rows: list[dict[str, Any]], part: ToolReturnPart) -> None:
    rows.append(
        {
            "id": f"tool-result-{part.tool_call_id}",
            "role": "tool",
            "content": part.model_response_str(),
            "toolCallId": part.tool_call_id,
        }
    )


def _append_retry(rows: list[dict[str, Any]], part: RetryPromptPart) -> None:
    # A retry scoped to a tool call is a failed tool result; the stable error
    # envelope mirrors what streaming persisted so downstream consumers can
    # count per-tool errors. A retry with no tool call is a model-level
    # validation retry and is not part of the visible turn.
    if not part.tool_call_id:
        return
    content = json.dumps({"error": part.model_response()}, separators=(",", ":"))
    rows.append(
        {
            "id": f"tool-result-{part.tool_call_id}",
            "role": "tool",
            "content": content,
            "toolCallId": part.tool_call_id,
        }
    )


def _open_tool_call_row(rows: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Return the last row iff it is an appendable tool-call row, else None.

    Consecutive tool calls group into one assistant row; any other part in
    between (text, reasoning, a tool return) leaves a non-tool-call row last and
    forces the next tool call to open a fresh row.
    """
    if not rows:
        return None
    last = rows[-1]
    if last.get("role") == "assistant" and "toolCalls" in last:
        return last
    return None


def _open_text_row(rows: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Return the last row iff it is an appendable assistant text row, else None.

    An assistant text row has no ``toolCalls``; a tool-call row (assistant +
    ``toolCalls``), a tool row, or a reasoning row in between leaves a non-text
    row last and forces the next text part to open a fresh row — mirroring the
    mapper, which closes the text section on a tool or reasoning event.
    """
    if not rows:
        return None
    last = rows[-1]
    if last.get("role") == "assistant" and "toolCalls" not in last:
        return last
    return None
